// Validate the agent.created contract (spec section 11) and build the
// receipt document stored in MongoDB via the Code Execution Service.
const item = $input.first().json;
const body = item.body || {};
const agent = body.agent || {};
const problems = [];
if (body.event !== 'agent.created') problems.push('event must be agent.created');
for (const field of ['id', 'name', 'provider', 'model']) {
  if (!agent[field]) problems.push('agent.' + field + ' is required');
}
const receivedAt = new Date().toISOString();
if (problems.length) {
  return [{ json: { valid: false, error: problems.join('; '), receivedAt } }];
}
const doc = {
  agent_id: String(agent.id),
  event: body.event,
  source: 'mindflow',
  received_at: receivedAt,
  agent: {
    name: agent.name,
    type: agent.type || 'ai',
    provider: agent.provider,
    model: agent.model,
    role: agent.role || '',
    skills: agent.skills || [],
    allowed_tools: agent.allowedTools || [],
    denied_scopes: agent.deniedScopes || [],
    token_limit_per_task: agent.tokenLimitPerTask ?? null,
    status: agent.status || ''
  }
};
return [{ json: { valid: true, receivedAt, agentId: doc.agent_id, event: body.event, doc } }];
